SELECT ?zone ?zoneName ?ts_id WHERE {
  ?sensor a brick:AirTemperatureSensor .
  ?sensor brick:hasPropertyType brick:AirTemperature ;
          brick:pointLocation ?zone .
  ?zone a brick:Zone ; rdfs:label ?zoneName .
  ?sensor ref:hasExternalReference ?ext .
  ?ext ref:hasTimeseriesId ?ts_id .
}

SELECT ?zone ?point ?label WHERE {
  ?zone a brick:Zone ; rdfs:label ?label .
  ?zone brick:hasPoint ?point .
  ?point a brick:AirTemperatureSensor .
} LIMIT 20

SELECT ?p ?loc ?label WHERE {
  ?p a brick:AirTemperatureSensor .
  ?p brick:pointLocation ?loc .
  ?loc rdfs:label ?label .
} LIMIT 20

SELECT ?p ?loc ?label WHERE {
  ?zone a brick:Zone .
  ?zone brick:hasPoint ?p .
  OPTIONAL { ?zone rdfs:label ?label }
} LIMIT 20

SELECT ?p ?loc ?label WHERE {
  ?p a brick:Zone_Air_Temperature_Sensor .
